import itertools

def is_proper_suffix(s, t):
    return s == t and s[::-1] == t

def find_max_proper_suffix(s, k):
    n = len(s) - k
    prefixes = itertools.accumulate(s[:(n + 1) // 2])[n // 2:]
    suffixes = itertools.accumulate(reversed(s[:(n + 1) // 2]))[::-1]
    max_length = -1
    for i, length in enumerate(prefixes, 1):
        if length % 2 and is_proper_suffix(s[:(n + 1) // 2], s[-length:]):
            max_length = max(max_length, length)
    return max_length

