from math import inf

def min_distance_to_hill(dists):
    n = len(dists)
    dp = [inf] * (n + 2)
    dp[0] = 0
    for i in range(1, n + 1):
        dp[i] = min(dp[(i - 1) // 2 + 1] + dists[i - 1], dp[i - 1] + 1)
    return dp[n]

def solve_testcase(num_holes, num_houses, houses):
    distances = [0] * num_houses
    for i in range(num_houses):
        distances[0 if num_holes % 2 == i % 2 else num_holes - 1] += abs(houses[i] // 2)
    return sum(min_distance_to_hill(distances[:i] + distances[idx:] for idx, dist in enumerate(distances) if dist >= num_holes // 2) for i in range(num_holes + 2))

T = int(input())
for _ in range(T):
    N, K = map(int, input().split())
    houses = list(map(int, input().split()))
