import math

def modular_inverse(a, m):
    """Calculate modular inverse of a modulo m."""
    a, m = a % m, m % m
    s, t = 1, 0
    s1, t1 = 0, 1
    while t != 0:
        q, u, v = divmod(a, t)
        a, t = t, u
        a = a - a * q
        s, s1 = s1, s1 - (s1 * q)
    return (s + m) % m

def factorial_mod_p(n, p):
    """
    Returns n! mod p, useful for computing multinomial coefficients modulo a prime.
    """
    result = 1
    for i in range(2, n + 1):
        result = result * i % p
    return result

def geometric_sum(a, n, p):
    """
    Returns a^n mod p, which is useful for computing probabilities in the problem.
    """
    return pow(a, n, p)

def partition_probability(seed_prob, steps, p_mod):
    """
    Computes the probability that the final number is i after a given number of steps.
    """
    if steps == 0:
        return seed_prob if seed_prob != 0 else 1
    if steps % 2 == 0:
        return geometric_sum(seed_prob * (seed_prob - 1), steps // 2, p_mod) * p_mod
    else:
        return geometric_sum((seed_prob - 1) * (seed_prob - 1), (steps - 1) // 2, p_mod) * p_mod

def main(N, M, seed_prob):
    """
    Main function to calculate the final probability distribution.
    """
    p_mod = pow(998244353, N, N) if N < 6 else pow(1010009, N, N)
    dp = [[0 for _ in range(N + 1)] for _ in range(max(N, steps) + 1)]
    dp[0][0] = 1
    for i in range(1, max(N, steps) + 1):
        for j in range(N + 1):
            if j < i:
                for k in range(j, i):
                    dp[i][k] += dp[i - 1][j] * partition_probability(seed_prob, i, p_mod)
                    dp[i][k] %= p_mod
            else:
                for k in range(i, N + 1):
                    dp[i][k] += dp[i - 1][j] * partition_probability(seed_prob, i, p_mod)
                    dp[i][k] %= p_mod
    return dp

Q = int(input())
for _ in range(Q):
    N, M = map(int, input().split())
    seed_prob = list(map(int, input().split()))
    dp = main(N, M, seed_prob)
    for val in dp[-1]:
        print(f"{val * Q % 998244353:09d}")

