To solve this problem, we need to use the Union-Find (Disjoint Set Union) data structure with path compression and union by rank. This data structure can efficiently manage information about groups of disjoint sets. Below is a Python code block that implements this solution:

```python
class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, p):
        if self.parent[p] != p:
            self.parent[p] = self.find(self.parent[p])
        return self.parent[p]

    def union(self, p, q):
        rootP = self.find(p)
        rootQ = self.find(q)
        if rootP == rootQ:
            return False
        elif self.rank[rootP] > self.rank[rootQ]:
            self.parent[rootQ] = rootP
        elif self.rank[rootP] < self.rank[rootQ]:
            self.parent[rootP] = rootQ
        else:
            self.parent[rootQ] = rootP
            self.rank[rootP] += 1
        return True

    def groups(self):
        result = {}
        for i in range(len(self.parent)):
            result[self.find(i)] = i
        return result

    def count_groups(self):
        return len(self.groups())

    def is_same_group(self, p, q):
        return self.find(p) == self.find(q)

    def get_biz_groups(self, p):
        return self.groups()[self.find(p)]

class Solution:
    def minimalBands(self, n: int, s: str, q: int, queries: List[List[int]]):
        uf = UnionFind(n)
        for i, (l, r) in enumerate(queries):
            for j in range(l-1, r):
                if not uf.is_same_group(i, j):
                    uf.union(i, j)

        colors = sorted({s[l-1] for l in range(1, q) if uf.is_same_group(0, l)})
        min_repeats = abs(len(colors) - q) + q + 1
        for i in range(q):
            min_repeats = min(min_repeats, len(np.unique(s))[1:-1] + 1)
        return ' '.join(str(min_repeats) for _ in range(q))

