def min_paint_cost(n: int, m: int, r: int, b: int, shields: List[Tuple[int, int]], constraints: List[Tuple[int, int, int]]) -> int:
    x, y = zip(*shields)
    distances = []
    for i in range(1000):
        row = set()
        for x, y in zip(x, y):
            distance = abs(y - y[i])
            if distance > 100:
                continue
            distances.append((distance, (x, y)))
        heapq.heapify(distances)
        for _ in range(m):
            #print(row)
            hits = set()
            pick = None
            while distances and (pick is None or pick > distances[-1][0]):
                distance, pos = heapq.heappop(distances)
                heapq.heapify(distances)
                row.remove(pos)
                hits.add(pos)
            if len(hits) < m:
                if pick is None:
                    pick = distances[0][0]
                else:
                    pick = max(pick, distances[0][0])
                while hits and len(hits) < m:
                    hull = (min(x for x, _ in row) << 20) + 0x7fffffff
                    hull += min(get_k(x, hull, n) for x, _ in row)
                    hull += max(get_k(x, hull, n) for x, _ in row)
                    row.remove((x, y[i]))
                    for g in hull[:m - len(hits)]:
                        heapq.heappush(distances, (2 * g - pick, (x, y)))
            else:
                if pick:
                    break
                elif hull:
                    break
                break
    else:
        hull = (min(x for x, _ in row) << 20)
        hull += min(get_k(x, hull, n) for x, _ in row)
        hull += max(get_k(x, hull, n) for x, _ in row)
        if hull < 0:
            return 0
        for g in hull[:m]:
            diff = 1 << 25
            if get_k(x, g, n) & diff:
                break
        else:
            return 0
    return r * hull + b * (n - hull)

