import math

def solve(n, m, points):
    if m == 0:
        return ([1, 1], [n-1, n-1])

    # Initialize the vertices with the bottom-left and top-right corners
    verts = [(1, 1), (n - 1, n - 1)]

    # Add the points in correct order using ray casting
    for i in range(m):
        threshold = 0
        if points[i][0] % 2 == 0:
            threshold = (n + points[i][0]) / 2
        if points[i][1] % 2 == 0:
            threshold = (n + points[i][1]) / 2
        dist_to_valid = (n - math.floor(threshold)) if threshold <= points[i][0] else points[i][1]

        l, r = -math.inf, -math.inf
        for j in range(i, min(len(points), m - i)):
            if (points[i][0] == points[j][0] and points[i][1] > points[j][1]) or (points[j][0] == points[i][0] and points[i][1] > points[j][1]):
                if points[j][0] < points[j][1]:
                    d = (points[j][1] - points[i][1]) / (points[j][0] - points[i][0] - 1)
                else:
                    d = (points[j][0] - points[i][0]) / (points[j][1] - points[i][1] - 1)
            else:
                d = (points[j][0] - points[r][0]) / (points[j][1] - points[r][1])
                l, r = r, j

            if d < dist_to_valid:
                verts.append(points[j])
                if r == -math.inf:
                    r = j
                elif r != i:
                    verts.append((points[r][0] + points[j][0]) / 2, (points[r][1] + points[j][1]) / 2)
                    l, r = r, j
                    dist_to_valid = d

    # Finish with complete sampling of remaining vertices
    dist_to_valid = 0.1e9
    for i in range(m):
        if points[i][0] % 2 == 0:
            dist_to_valid = max(dist_to_valid, (n + points[i][0]) / 2)
        if points[i][1] % 2 == 0:
            dist_to_valid = max(dist_to_valid, (n + points[i][1]) / 2)
        dist_to_valid = (n + dist_to_valid) / 2
        l, r = -math.inf, -math.inf
        for j in range(i, min(len(points), m - i)):
            dist_to_valid_thresh = (n + points[j][0]) / 2
            if points[j][0] % 2 == 0:
                dist_to_valid_thresh = n + points[j][0]
            if points[j][1] % 2 == 0:
                dist_to_valid_thresh = n + points[j][1]

            if dist_to_valid - dist_to_valid_thresh < (dist_to_valid - dist_to_valid_thresh) / 2.0:
                elz = math.sqrt(pow(n - points[i][0], 2) + pow(n - points[i][1], 2))
                l = points[i]
                miss = False
                for kk in range(i + 1, m - i):
                    prev = None if i + 1 == m - i else points[i + 1]
                    farthest = None if kk + 1 == min(len(points), m - m + i) else points[kk + 1]
                    dist_to_valid_thresh = dist_to_valid_thresh if miss else dist_to_valid_thresh + miss
                    for k in range(kk, min(len(points), m - kk + i)):
                        dist_to_valid = (n - max(points[k][0], points[kk][0])) / 2
                        dist_x = max(points[k][0], prev[0], points[kk][0], farthest[0]) - min(points[k][0], prev[0], points[kk][0], farthest[0])
                        dist_y = max(points[k][1], points[kk][1]) - min(points[k][1], points[kk][1])
                        if dist_to_valid_thresh > dist_to_valid - dist_x - dist_y:
                            miss = True
                        if dist_to_valid - dist_x > dist_to_valid_thresh:
                            l = points[k]
                            miss = True
                    if (not miss) and (k + 1 < len(points) or kk + 1 < m):
                        if dist_to_valid_thresh > ((n + points[k])[-1]) or ((n-1 - points[i])[-1] < points[k][-1]):
                            verts.append(points[k])
                            l, r = r, k
                            miss = True
                    if dist_to_valid_thresh > ((n + points[kk])[1]) or ((n-1 - points[i])[-1] < points[kk][1]):
                        verts.append(points[kk])
                        l, r = r, k
                    else:
                        miss = (l, r) != (points[i], points[k])
                        break
        if r == -math.inf:
            r = i + 1
        elif r != i:
            verts.append((points[r][0] + points[i][0]) / 2, (points[r][1] + points[i][1]) / 2)

    return (verts)

