def intersects_path(point, path, total_points, n, m):
    x, y = point
    intersects = 0
    for i in range(total_points):
        if x == m or y == n:
            break
        if (path[i][0] + 1, path[i][1]) == point:
            x += 1
        elif (path[i][0] - 1, path[i][1]) == point:
            x -= 1
        elif (path[i][0], path[i][1] + 1) == point:
            y += 1
        elif (path[i][0], path[i][1] - 1) == point:
            y -= 1
        if path[0] == point and path[1] == point:
            intersects = (x != 0) + (y != 0)
    return intersects % 2

